#include <stdio.h>
#include <stdlib.h>

#define MAXN 100005

int parent[MAXN];

int find_set(int v) {
    if (v == parent[v])
        return v;
    return parent[v] = find_set(parent[v]);
}

int union_sets(int a, int b) {
    a = find_set(a);
    b = find_set(b);
    if (a != b) {
        parent[b] = a;
        return 1;
    }
    return 0;
}

typedef struct {
    int u, v, t;
} Edge;

Edge edges[MAXN];

int main() {
    int n, m, k;
    if (scanf("%d %d %d", &n, &m, &k) != 3)
        return 0;

    for (int i = 1; i <= n; i++) {
        parent[i] = i;
    }

    int water_cycle = 0;

    for (int i = 0; i < m; i++) {
        scanf("%d %d %d", &edges[i].u, &edges[i].v, &edges[i].t);
        if (edges[i].t == 1) {
            if (!union_sets(edges[i].u, edges[i].v)) {
                water_cycle = 1;
            }
        }
    }

    if (water_cycle) {
        printf("N\n");
        return 0;
    }

    /* Agora conectamos também as rodovias para contar os componentes do grafo total */
    for (int i = 0; i < m; i++) {
        if (edges[i].t == 2) {
            union_sets(edges[i].u, edges[i].v);
        }
    }

    int components = 0;
    for (int i = 1; i <= n; i++) {
        if (find_set(i) == i) {
            components++;
        }
    }

    /* O número mínimo de arestas a remover para eliminar todos os ciclos é M - N + C */
    long long needed_removals = (long long)m - n + components;

    if (needed_removals <= k) {
        printf("S\n");
    } else {
        printf("N\n");
    }

    return 0;
}
